.wdt-custom-filler-right .wdt-content-description ul {
  list-style: none; /* remove default bullets */
  padding: 0;
  margin: 0;
  text-align: right; /* right align list items */
}

.wdt-custom-filler-left .wdt-content-description ul {
  list-style: none; /* remove default bullets */
  padding: 0;
  margin: 0;
  text-align: left; /* right align list items */
}

.wdt-content-description ul li {
  position: relative;
/*   border-bottom: 1px solid #fff; */
  padding: 5px 20px 5px 10px; /* extra right padding for bullet space */
  margin: 5px;
  border-radius: 4px;
}

/* Add bullet (disc) on the right side */
.wdt-custom-filler-right .wdt-content-description ul li::after {
  content: "•"; /* bullet */
  position: absolute;
  right: 5px; /* adjust spacing */
  top: 50%;
  transform: translateY(-50%);
  font-size: 18px;
  color: #fff; /* bullet color */
}

.wdt-custom-filler-left .wdt-content-description ul li::after {
  content: "•"; /* bullet */
  position: absolute;
  left: -10px; /* adjust spacing */
  top: 50%;
  transform: translateY(-50%);
  font-size: 18px;
  color: #fff; /* bullet color */
}

