@import url('https://fonts.googleapis.com/css2?family=Cambay:ital,wght@0,400;0,700;1,400;1,700&family=Exo+2:ital,wght@0,100..900;1,100..900&family=Manrope:wght@200..800&family=Onest:wght@100..900&family=Quantico:ital,wght@0,400;0,700;1,400;1,700&display=swap');
</style>
<style>
    :root{
        --wdtFontTypo_Alt: 'Quantico', sans-serif;
        --wdtFontTypo_H1: 'Quantico', sans-serif;
        --wdtFontTypo_H2: 'Quantico', sans-serif;
        --wdtFontTypo_H3: 'Quantico', sans-serif;
        --wdtFontTypo_H4: 'Quantico', sans-serif;
        --wdtFontTypo_H5: 'Quantico', sans-serif;
        --wdtFontTypo_H6: 'Quantico', sans-serif;
        --wdtFontTypo_Base: 'Cambay', sans-serif;

        /* Updated Brand Colors */
        --wdtPrimaryColor: #29aae2;
        --wdtPrimaryColorRgb: 41, 170, 226;
        --wdtLinkHoverColor: #007aff;
        --wdtLinkHoverColorRgb: 0, 122, 255;
        --wdtSecondaryColor: #007aff;
        --wdtTertiaryColor: #1E1616;
        --wdtBodyBGColor: #171313;

        /* Added missing variable for consistency */
        --wdtHeadAltColor: #ffffff;
    }
    
h1, h2, h3, h4, h5, h6{
    font-family: 'Quantico', sans-serif;
}
body{
    font-family: 'Cambay', sans-serif;
}
#back-to-top { border-radius: 0; }


/* Popup_Close Button */
.wdt-popup-box-window .wdt-popup-box-content-holder .mfp-close:hover,
.wdt-popup-box-window .mfp-close:hover,
.wdt-popup-box-window.mfp-wrap .mfp-container.mfp-inline-holder .mfp-content .wdt-popup-box-content-holder .wdt-popup-box-content-inner ~ .mfp-close:hover,
.wdt-popup-box-window .wdt-popup-box-content-holder .mfp-close,
.wdt-popup-box-window .mfp-close,
.wdt-popup-box-window.mfp-wrap .mfp-container.mfp-inline-holder .mfp-content .wdt-popup-box-content-holder .wdt-popup-box-content-inner ~ .mfp-close {
    color: var(--wdtHeadAltColor) !important;
}

.select2-container--default .select2-results .select2-results__option--highlighted[aria-selected]{
    color: var(--wdtHeadAltColor);
}
.woocommerce.single-product div.images span.onsale,
.woocommerce-product-gallery span.onsale,
.wdt-product-image-gallery-container span.onsale,
#yith-quick-view-content span.onsale,
.woocommerce.single-product div.images span.out-of-stock,
.woocommerce-product-gallery span.out-of-stock,
.wdt-product-image-gallery-container span.out-of-stock,
#yith-quick-view-content span.out-of-stock {
    color: var(--wdtHeadAltColor);
}
body[class*="woocommerce"] .yith-wcqv-wrapper #yith-quick-view-close{
    color: var(--wdtHeadAltColor);
    border: 0;
}
.woocommerce a.button, .woocommerce button.button{
    color:  var(--wdtHeadAltColor) !important;
}
.woo-variation-swatches .wvs-style-squared.variable-items-wrapper .variable-item:not(.radio-variable-item){
    font-family: var(--wdtFontTypo_Alt);
}
.woo-variation-swatches .variable-items-wrapper .variable-item:not(.radio-variable-item).button-variable-item.selected:not(.no-stock),
.woo-variation-swatches .variable-items-wrapper .variable-item:not(.radio-variable-item).button-variable-item:not(.no-stock):hover{
    color: var(--wdtHeadAltColor);
}
.woocommerce div.product div.summary .stock,
.woocommerce div.product.type-product > div.summary p.stock{
    color: var(--wdtHeadAltColor);
}
.woocommerce ul.products li.product .product-buttons-wrapper.product-icons a:hover{
    color: var(--wdtHeadAltColor);
}
.elementor-widget-container .wdt-heading-holder .wdt-heading-subtitle-wrapper{
    text-transform: uppercase;
}
</style>
