<style>
 /* Unique Section */
 .tankless-hero-section {
 position: relative;
 width: 100%;
 height: 650px;
 overflow: hidden;
 border: 2px solid #29aae2;
 background: url('http://localhost/thetankless/wp-content/uploads/2025/10/freepik__tankless-water-heaters-installation-on-a-matte-bla__7179-1-1.png') center/cover no-repeat;
 }

 .tankless-hero-overlay {
 position: absolute;
 inset: 0;
 background: rgba(0,0,0,0.45);
 z-index: 1;
 }

 /* Play Button */
 .tankless-hero-play-btn {
 position: absolute;
 top: 50%;
 left: 50%;
 transform: translate(-50%, -50%);
 width: 80px;
 height: 80px;
 border-radius: 50%;
 background-color: rgba(255,255,255,0.2);
 border: 2px solid rgba(255,255,255,0.4);
 display: flex;
 align-items: center;
 justify-content: center;
 cursor: pointer;
 transition: 0.3s ease;
 z-index: 3;
 }

 .tankless-hero-play-btn:hover { background-color: rgba(255,255,255,0.4); }

 .tankless-hero-play-btn::before {
 content: '';
 width: 0;
 height: 0;
 border-left: 18px solid white;
 border-top: 10px solid transparent;
 border-bottom: 10px solid transparent;
 margin-left: 5px;
 }

 /* Text Content */
 .tankless-hero-content {
 position: absolute;
 bottom: 40px;
 left: 50px;
 color: #fff;
 max-width: 520px;
 z-index: 2;
 }

 .tankless-hero-content h2 {
 font-size: 28px;
 font-weight: 700;
 margin-bottom: 8px;
 }

 .tankless-hero-content p {
 font-size: 15px;
 line-height: 1.6;
 opacity: 0.9;
 margin-bottom: 12px;
 }

 .tankless-hero-content a {
 color: #29aae2;
 font-weight: 600;
 text-decoration: none;
 }

 /* Popup Modal */
 .tankless-hero-popup {
 position: fixed;
 inset: 0;
 background: rgba(0,0,0,0.9);
 display: none;
 align-items: center;
 justify-content: center;
 z-index: 1000;
 animation: fadeInHero 0.3s ease;
 }

 .tankless-hero-popup.active { display: flex; }

 .tankless-hero-popup video {
 width: 80%;
 max-width: 960px;
 border-radius: 10px;
 outline: none;
 }

 .tankless-hero-close {
 position: absolute;
 top: 25px;
 right: 35px;
 font-size: 32px;
 color: #fff;
 cursor: pointer;
 transition: 0.3s;
 }

 .tankless-hero-close:hover { color: #29aae2; }

 @keyframes fadeInHero { from {opacity: 0;} to {opacity: 1;} }

 /* Mobile Responsive */
 @media (max-width: 768px) {
 .tankless-hero-section { height: 360px; }

 .tankless-hero-content {
 left: 25px;
 right: 25px;
 bottom: 30px;
 display: none;
 }

 .tankless-hero-popup video {
 width: 95%;
 height: auto;
 max-height: 80vh;
 }
 }
</style>
<body>

<!-- Static Image Section -->
<div class="tankless-hero-section">
 <div class="tankless-hero-overlay"></div>

 <div class="tankless-hero-play-btn" id="tanklessOpenPopup"></div>

 <div class="tankless-hero-content">
 <h2>Ready to Go Tankless?</h2>
 <p>Up to 0.95 UEF and ENERGY STAR® certified options. Real-time display shows water flow, pump activity, flame presence & standby mode. Optional Wi-Fi and OneTouch Hot Water remote kit.</p>
 <a href="#" id="tanklessWatchLink">Watch Video From One Of Our Dealers</a>
 </div>
</div>

<!-- Video Popup -->
<div class="tankless-hero-popup" id="tanklessVideoPopup">
 <span class="tankless-hero-close" id="tanklessClosePopup">&times;</span>
 <video controls id="tanklessPopupVideo">
 <source src="https://lghomecomfort.ca/wp-content/uploads/2025/10/TheTanklessLandingPage_Under81Mb.mp4" type="video/mp4">
 </video>
</div>

<script>
 const openBtn = document.getElementById('tanklessOpenPopup');
 const closeBtn = document.getElementById('tanklessClosePopup');
 const popup = document.getElementById('tanklessVideoPopup');
 const watchLink = document.getElementById('tanklessWatchLink');
 const video = document.getElementById('tanklessPopupVideo');

 function openVideo() {
 popup.classList.add('active');
 // Wait a short moment to ensure popup is visible before playing
 setTimeout(() => {
 video.play();
 }, 150);
 }

 function closeVideo() {
 popup.classList.remove('active');
 video.pause();
 video.currentTime = 0;
 }

 openBtn.addEventListener('click', openVideo);
 watchLink.addEventListener('click', e => {
 e.preventDefault();
 openVideo();
 });
 closeBtn.addEventListener('click', closeVideo);
 popup.addEventListener('click', (e) => {
 if (e.target === popup) closeVideo();
 });
</script>

</body>
