<html lang="en">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width, initial-scale=1" />
<title>Why Choosing Tankless vs Tank Water Heater</title>
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Cambay:wght@400;600&display=swap" rel="stylesheet">
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700;800&display=swap" rel="stylesheet">
<style>
 * {
 box-sizing: border-box;
 }

 /*body {*/
 /* margin: 0;*/
 /* font-family: Inter, system-ui, -apple-system, Segoe UI, Roboto, "Helvetica Neue", Arial, "Noto Sans", "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol";*/
 background: #0f0e10; /* Dark Background */
 color: #fff; /* White Text */
 /* line-height: 1.5;*/
 /*}*/

 /* General Section Style */
 .section {
 max-width: 100%;
 margin: 0 auto;
 padding: clamp(20px, 3vw, 40px);
 position: relative;
 overflow: hidden;
 }

 .heading {
 font-weight: 800;
 font-size: clamp(22px, 2.4vw, 36px);
 line-height: 1.25;
 margin: 6px 0 24px;
 letter-spacing: .1px;
 }
 .heading .blue {
 color: #29aae2; /* Blue */
 }

 .subheading {
 font-size: clamp(18px, 1.6vw, 24px);
 margin: 0 0 28px;
 color: #fff; /* White */
 opacity: .9;
 }

 /* Layout */
 .grid {
 display: grid;
 grid-template-columns: 100%;
 gap: clamp(16px, 2vw, 28px);
 align-items: start;
 }

 /* Tank and Tankless Content */
 .stack {
 display: flex;
 flex-direction: column;
 gap: clamp(12px, 1.4vw, 16px);
 font-family: Cambay, sans-serif; /* Cambay font */
 }

 .card {
 display: flex;
 gap: 12px;
 align-items: center;
 background: linear-gradient(180deg, rgba(255, 255, 255, .03), rgba(255, 255, 255, .01));
 border: 1px solid rgba(255, 255, 255, .08); /* Border Color */
 border-radius: 12px;
 padding: 14px 16px;
 min-height: 68px;
 }

 .card p {
 margin: 0;
 font-size: 14.5px;
 color: #b8b7bb; /* Muted Text */
 }

 .card strong {
 color: #fff; /* White Text */
 font-weight: 600;
 }

 /* Icon badges */
 .icon {
 flex: 0 0 28px;
 width: 28px;
 height: 28px;
 display: grid;
 place-items: center;
 border-radius: 8px;
 }

 .icon.red {
 background: rgba(255, 75, 75, .12);
 border: 1px solid rgba(255, 75, 75, .25);
 }

 .icon.blue {
 background: rgba(41, 170, 226, .12);
 border: 1px solid rgba(41, 170, 226, .28);
 }

 .icon svg {
 width: 16px;
 height: 16px;
 }

 /* Right column text sizing a bit bigger */
 .pros .card p {
 color: #dceaf2;
 }

 /* Small caption under H1 (optional) */
 .eyebrow {
 color: #9b98a1;
 text-transform: uppercase;
 font-weight: 700;
 letter-spacing: .14em;
 font-size: 11px;
 }

 /* Subtle top fade for depth */
 .fade-top {
 position: absolute;
 inset: 0 0 auto 0;
 height: 120px;
 background: linear-gradient(180deg, rgba(255, 255, 255, .06), rgba(255, 255, 255, 0));
 pointer-events: none;
 }
</style>
</head>
<body>

<!-- Tank Water Heater Section -->
<div class="section">
 
 <div class="grid">
 <!-- LEFT: Cons -->
 <div class="stack cons">
 <div class="card">
 <span class="icon red" aria-hidden="true">
 <!-- X icon -->
 <svg viewBox="0 0 24 24" fill="none" stroke="#ff4b4b" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
 <path d="M18 6L6 18M6 6l12 12"/>
 </svg>
 </span>
 <p><strong>Wastes $200+ in energy every year</strong></p>
 </div>

 <div class="card">
 <span class="icon red" aria-hidden="true">
 <svg viewBox="0 0 24 24" fill="none" stroke="#ff4b4b" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
 <path d="M18 6L6 18M6 6l12 12"/>
 </svg>
 </span>
 <p><strong>Takes up 16+ sq. ft. of floor space</strong></p>
 </div>

 <div class="card">
 <span class="icon red" aria-hidden="true">
 <svg viewBox="0 0 24 24" fill="none" stroke="#ff4b4b" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
 <path d="M18 6L6 18M6 6l12 12"/>
 </svg>
 </span>
 <p><strong>Limited hot water—runs out in 20 min</strong></p>
 </div>
 <div class="card">
 <span class="icon red" aria-hidden="true">
 <svg viewBox="0 0 24 24" fill="none" stroke="#ff4b4b" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
 <path d="M18 6L6 18M6 6l12 12"/>
 </svg>
 </span>
 <p><strong>Shorter lifespan: 8–12 years</strong></p>
 </div>
 <div class="card">
 <span class="icon red" aria-hidden="true">
 <svg viewBox="0 0 24 24" fill="none" stroke="#ff4b4b" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
 <path d="M18 6L6 18M6 6l12 12"/>
 </svg>
 </span>
 <p><strong>Risk of tank failure and flooding</strong></p>
 </div>
 </div>

 <!-- RIGHT: Pros -->
 <div class="stack pros">
 <div class="card">
 <span class="icon blue" aria-hidden="true">
 <!-- Check icon -->
 <svg viewBox="0 0 24 24" fill="none" stroke="#29aae2" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round">
 <path d="M20 6L9 17l-5-5"/>
 </svg>
 </span>
 <p><strong>Lower initial purchase cost</strong></p>
 </div>
 </div>
 </div>
</div>



</body>
</html>
